//! Adversarial tests for the hardened Hermes deny list (2026-10-29).
//!
//! `tests/denylist/corpus.json` holds every payload (generated by
//! `tests/denylist/make_corpus.py`); `prior-results.json` is what the PRIOR
//! Python command-guard plugin did with each one (`audit_prior.py`, run on the
//! backup copies). One test per bypass class: every payload must be refused,
//! every benign call must pass, and nothing the prior list refused may pass.

use hermes_rs::denylist::{check_command, check_tool_call, Mode, Policy};
use serde_json::{json, Value};
use std::path::PathBuf;

fn workspace() -> PathBuf {
    let d = std::env::temp_dir().join("hermes-denylist-test-ws");
    std::fs::create_dir_all(d.join("src")).unwrap();
    d
}

fn policy() -> Policy {
    Policy::workspace(workspace())
}

fn corpus() -> Vec<Value> {
    serde_json::from_str(include_str!("denylist/corpus.json")).unwrap()
}

fn verdict(tool: &str, params: &Value, pol: &Policy) -> Result<(), String> {
    check_tool_call(tool, params, pol).map_err(|d| d.to_string())
}

fn class(name: &str) {
    let pol = policy();
    let cases: Vec<Value> = corpus()
        .into_iter()
        .filter(|c| c["class"] == name)
        .collect();
    assert!(!cases.is_empty(), "no cases for {name}");
    let mut leaks = Vec::new();
    for c in &cases {
        let tool = c["tool"].as_str().unwrap();
        let r = verdict(tool, &c["params"], &pol);
        let want_deny = c["expect"] == "deny";
        if want_deny != r.is_err() {
            leaks.push(format!("{tool} {} -> {r:?}", c["params"]));
        }
    }
    assert!(
        leaks.is_empty(),
        "{name}: {} wrong of {}:\n{}",
        leaks.len(),
        cases.len(),
        leaks.join("\n")
    );
}

